self.KB_CONTENT["card:751908"]={"id":"card:751908","ty":"card","sourceId":"751908","title":"『會計傳票建立作業』中的『立沖科目明細：開帳資料來自於立沖帳目餘額。』為何？","ver":"iGP","topic":"立沖帳目","keywords":["立沖帳目","明細","科目","傳票"],"y":"other","answer":"A.非立沖帳：為預留功能。B.立沖帳目一(立帳)：為預留功能。C.立沖帳目一(沖帳)：為預留功能。D.立沖帳目二(立帳)：為預留功能。E.立沖帳目二(沖帳)：為預留功能。* 預設為「無」。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
