self.KB_CONTENT["card:783864"]={"id":"card:783864","ty":"card","sourceId":"783864","title":"『資產採購變更作業』的作業重點有哪些？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","變更單","資產","採購"],"y":"explain","answer":"1.若採購變更單頭為整張結案，則單身不可輸入。2.若採購變更單不存在進貨單，或存在進貨單但確認碼=V(作廢)時，才可做取消確認。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
