self.KB_CONTENT["card:792857"]={"id":"card:792857","ty":"card","sourceId":"792857","title":"『標準成本計算條件建立作業』中的『人工成本 (CST.MZ011)』為何？","ver":"GP4以上","topic":"單位","keywords":["單位","人工","線別"],"y":"other","answer":"* 計1.依本階標準人工成本及2.依標準工時*線別標準單位人工成本兩種。* 若人工成本「依標準工時*線別標準單位人工成本」時， [標準工時] 欄位才可輸入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
