self.KB_CONTENT["card:780278"]={"id":"card:780278","ty":"card","sourceId":"780278","title":"『進口費用建立作業』中的『交易幣別 (TJ008)』為何？","ver":"GP4以上","topic":"費用","keywords":["費用","幣別","交易","進口"],"y":"other","answer":"* 預設本國幣別。亦可修改，點選或[F2]幣別資料查詢.但不允許空白。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
