self.KB_CONTENT["field:819930"]={"id":"field:819930","ty":"field","sourceId":"819930","title":"預計收支建立作業","ver":"iGP 1.0.10以上","topic":"","keywords":[],"job":"資金預估明細表","code":"","answer":"『資金預估明細表』中的『預計收入』、『預計支出』是抓『預計收支建立作業-NOTI05』的內容來呈現的。銷售預測建立作業的內容不納入資金預估明細表中。","file":"fields.jsonl"};
