self.KB_CONTENT["field:784454"]={"id":"field:784454","ty":"field","sourceId":"784454","title":"單號","ver":"GP4以上","topic":"","keywords":[],"job":"資產出售建立作業","code":"TC002","answer":"* 單據單號。* 編碼方式為「手動編號」須自行輸入不可空白，並不可重覆，其餘自動預設單號資料。","file":"fields.jsonl"};
